<?php
require __DIR__.'/../includes/upb_bj_input_template.php';
function checkUpb($ok,$message){if(!$ok)throw new RuntimeException($message);}
function editUpb(string $bytes,callable $edit): string {$p=tempnam(sys_get_temp_dir(),'upb-fixture-');try{file_put_contents($p,$bytes);$z=new ZipArchive();$z->open($p);$d=upbBjXml($z->getFromName('content.xml'));$edit($d);$z->addFromString('content.xml',$d->saveXML());$z->close();return file_get_contents($p);}finally{unlink($p);}}
function docUpb(string $bytes):DOMDocument {$p=tempnam(sys_get_temp_dir(),'upb-read-');try{file_put_contents($p,$bytes);$z=new ZipArchive();$z->open($p);$xml=$z->getFromName('content.xml');$z->close();return upbBjXml($xml);}finally{unlink($p);}}
$fixture=editUpb(buildUpbBjInputTemplateOds('2026-02'),function($d){$tables=upbBjTables($d);foreach(['JANUARI'=>[100,20,5],'FEBRUARI'=>[160,35,9]] as $name=>$values){$t=$tables[$name];$bottom=upbBjBottom($t);$cells=upbBjCells($t);foreach(['FARMASI','SOBISCO','CANDY'] as $i=>$label){$row=(int)substr($bottom[$label]['ref'],1);$cell=$cells[$row][9];$cell->removeAttributeNS(UPB_T,'formula');$cell->setAttributeNS(UPB_O,'office:value',(string)$values[$i]);$cell->textContent=(string)$values[$i];}
 // Populate real product rows so rebuilt subgroup/GB subtotals agree with bottom totals.
 $r=1;foreach($t->childNodes as $node)if($node instanceof DOMElement&&$node->localName==='table-row'){foreach([7=>$values[0],89=>$values[1],158=>$values[2]] as $productRow=>$amount)if($r===$productRow){$cell=upbBjColumnCell($node,9);$cell->setAttributeNS(UPB_O,'office:value-type','float');$cell->setAttributeNS(UPB_O,'office:value',(string)$amount);$cell->textContent=(string)$amount;}$r+=max(1,(int)$node->getAttributeNS(UPB_T,'number-rows-repeated'));}
 // Shift every bottom summary by inserted rows, just as changing product row counts does.
 $firstRow=(int)substr($bottom['FARMASI']['ref'],1);$node=null;$r=1;foreach($t->childNodes as $child)if($child instanceof DOMElement&&$child->localName==='table-row'){if($r===$firstRow){$node=$child;break;}$r+=max(1,(int)$child->getAttributeNS(UPB_T,'number-rows-repeated'));}
 for($i=0;$i<3;$i++)$t->insertBefore($d->createElementNS(UPB_T,'table:table-row'),$node);
 if($name==='FEBRUARI'){$removed=0;foreach(iterator_to_array($t->childNodes) as $child){if(!$child instanceof DOMElement||$child->localName!=='table-row')continue;if((float)upbBjColumnCell($child,9)->getAttributeNS(UPB_O,'value')!==0.0)continue;foreach($child->childNodes as $cell){if($cell===$child->firstChild&&$cell instanceof DOMElement&&$cell->getAttributeNS(UPB_O,'value-type')==='float'&&trim($cell->textContent)!==''){$t->removeChild($child);$removed++;break;}}if($removed===2)break;}}
 upbBjApplySubtotals($t);
 }});
validateUpbBjOds($fixture,'2026-02');
$out=buildUpbBjInputTemplateOds('2026-03',$fixture);$d=docUpb($out);$tables=upbBjTables($d);checkUpb(array_keys($tables)===['JANUARI','FEBRUARI','MARET','KESIMPULAN'],'Sheet sequence');
foreach(['JANUARI'=>100,'FEBRUARI'=>160] as $name=>$value)checkUpb(upbBjBottom($tables[$name])['FARMASI']['value']===$value*1.0,'History amount retained');checkUpb(upbBjBottom($tables['MARET'])['FARMASI']['value']===0.0,'New month empty');
$cells=upbBjCells($tables['KESIMPULAN']);checkUpb((float)$cells[10][4]->getAttributeNS(UPB_O,'value')===0.1,'January standalone');checkUpb((float)$cells[10][5]->getAttributeNS(UPB_O,'value')===0.06,'February difference');checkUpb((float)$cells[11][5]->getAttributeNS(UPB_O,'value')===0.015,'Sobisco February');checkUpb((float)$cells[12][5]->getAttributeNS(UPB_O,'value')===0.004,'Candy February');checkUpb(abs((float)$cells[13][5]->getAttributeNS(UPB_O,'value')-0.079)<1e-12,'Monthly total');
$jan=upbBjBottom($tables['JANUARI'])['FARMASI']['ref'];$feb=upbBjBottom($tables['FEBRUARI'])['FARMASI']['ref'];checkUpb($cells[10][5]->getAttributeNS(UPB_T,'formula')==="of:=(['FEBRUARI'.".$feb."]-['JANUARI'.".$jan."])/1000",'Simple dynamic-row formula');
$january=upbBjTables(docUpb(buildUpbBjInputTemplateOds('2026-01',$fixture)));checkUpb(array_keys($january)===['JANUARI','KESIMPULAN'],'January download only includes January');checkUpb(upbBjBottom($january['JANUARI'])['FARMASI']['value']===100.0,'Saved same-year January must not be reset');
validateUpbBjOds($out,'2026-03');$reset=upbBjTables(docUpb(buildUpbBjInputTemplateOds('2027-01',$fixture)));checkUpb(array_keys($reset)===['JANUARI','KESIMPULAN'],'January reset sheets');checkUpb(upbBjBottom($reset['JANUARI'])['FARMASI']['value']===0.0,'January reset values');
file_put_contents('/tmp/upb-history-test.ods',$out);
$sample=[1=>['FARMASI'=>['ref'=>'I182','value'=>10000000000.0],'SOBISCO'=>['ref'=>'I183','value'=>0.0],'CANDY'=>['ref'=>'I184','value'=>0.0]]];
upbBjFillConclusion($tables['KESIMPULAN'],$sample,1,['JANUARI']);$formatted=upbBjCells($tables['KESIMPULAN']);checkUpb($formatted[10][4]->textContent==='10,000,000','Comma grouping with no decimals');checkUpb((float)$formatted[10][4]->getAttributeNS(UPB_O,'value')===10000000.0,'Divide monthly amount by 1000');checkUpb($formatted[10][4]->getAttributeNS(UPB_T,'formula')==="of:=['JANUARI'.I182]/1000",'Simple January formula');checkUpb($formatted[10][4]->getAttributeNS(UPB_T,'style-name')==='UPBSummaryNumber','Numeric display style');checkUpb($formatted[10][2]->textContent==='10,000,000','Left YTD sums formatted monthly values');checkUpb($formatted[10][2]->getAttributeNS(UPB_T,'style-name')==='UPBSummaryNumber','Left summary numeric style');checkUpb($formatted[10][2]->getAttributeNS(UPB_T,'formula')==='of:=SUM([.D10:.D10])','January YTD simple SUM');
echo "PASS: cumulative differences, simple formulas, saved monthly sheets, new blank month, added/deleted product rows, upload validation and January/year reset.\n";
